<?php
namespace App\Http\Controllers;

use App\Models\{AdminApiToken,CareerActivity,CareerApplication,CareerJob,CareerMessage,ContactInquiry,ContactReply,DonationInterest,DonationInterestReply,User};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,Mail,Storage};
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;

class CareerController extends Controller
{
    private function actor(): ?User { return request()->user(); }
    private function activity(CareerApplication $app,string $event,array $details=[]): void { $app->activity()->create(['user_id'=>$this->actor()?->id,'event_type'=>$event,'details'=>$details]); }
    private function superadmin(): void { abort_unless($this->actor()?->role==='superadmin',403,'Superadmin access required.'); }
    private function slug(string $title): string { return Str::slug($title).'-'.Str::lower(Str::random(4)); }

    public function jobs(){return response()->json(['jobs'=>CareerJob::where('is_open',true)->orderBy('id')->get(['id','reference','slug','title','location','department','employment_type','summary','responsibilities','qualifications','hero_image'])]);}
    public function jobBySlug(string $slug){return CareerJob::where('slug',$slug)->where('is_open',true)->firstOrFail();}
    public function contact(Request $r){$d=$r->validate(['name'=>'required|string|max:160','email'=>'required|email:rfc|max:190','phone'=>'nullable|string|max:50','country'=>'nullable|string|max:120','topic'=>'required|string|max:140','message'=>'required|string|max:10000','consent'=>'required|accepted']);$entry=ContactInquiry::create(['reference'=>'CON-'.strtoupper(Str::random(8)),'name'=>$d['name'],'email'=>$d['email'],'phone'=>$d['phone']??null,'country'=>$d['country']??null,'topic'=>$d['topic'],'message'=>$d['message'],'consent_at'=>now(),'status'=>'new']);return response()->json(['contact'=>['reference'=>$entry->reference]],201);}
    public function apply(Request $r){
        $d=$r->validate(['jobReference'=>'required|exists:career_jobs,reference','firstName'=>'required|string|max:100','lastName'=>'required|string|max:100','email'=>'required|email:rfc|max:190','phone'=>'nullable|string|max:50','location'=>'required|string|max:190','area'=>'required|string|max:100','experience'=>'nullable|string|max:50','linkedin'=>'nullable|url|max:500','consent'=>'required|accepted','resume'=>'required|file|mimes:pdf,doc,docx,rtf|max:20480','coverLetter'=>'nullable|file|mimes:pdf,doc,docx,rtf|max:20480','website'=>'nullable|string|max:0']);
        $resume=$r->file('resume')->store('career-applications/'.Str::uuid(),'local');$support=$r->file('coverLetter')?->store('career-applications/'.Str::uuid(),'local');$job=CareerJob::where('reference',$d['jobReference'])->where('is_open',true)->firstOrFail();
        $app=CareerApplication::create(['career_job_id'=>$job->id,'reference'=>$job->reference.'-'.strtoupper(Str::random(8)),'first_name'=>$d['firstName'],'last_name'=>$d['lastName'],'email'=>$d['email'],'phone'=>$d['phone']??null,'location'=>$d['location'],'area_of_interest'=>$d['area'],'experience'=>$d['experience']??null,'linkedin_url'=>$d['linkedin']??null,'status'=>'received','resume_path'=>$resume,'resume_name'=>$r->file('resume')->getClientOriginalName(),'supporting_path'=>$support,'supporting_name'=>$r->file('coverLetter')?->getClientOriginalName(),'consent_at'=>now(),'submitted_at'=>now()]);
        $this->activity($app,'application_submitted',['reference'=>$app->reference]);$confirmation=$this->sendMail($app,$app->email,'We received your application for '.$job->title,"Dear {$app->first_name},\n\nThank you for applying for {$job->title}. Your reference is {$app->reference}. Our recruiting team will review your information.\n\nHamilton Medical Recruiting");$recruiter=env('RECRUITING_EMAIL');$notification=$recruiter?$this->sendMail($app,$recruiter,'New application '.$app->reference,"{$app->first_name} {$app->last_name} applied for {$job->title}.\nEmail: {$app->email}\nReference: {$app->reference}"):false;
        return response()->json(['application'=>['id'=>$app->id,'reference'=>$app->reference],'confirmationEmail'=>$confirmation,'recruitingNotification'=>$notification],201);
    }
    private function sendMail(CareerApplication $app,string $to,string $subject,string $body): bool {try{if(config('mail.default')==='log')throw new \RuntimeException('Mail is configured for local logging only. Configure SMTP to deliver email.');Mail::raw($body,fn($m)=>$m->to($to)->subject($subject));$app->messages()->create(['user_id'=>$this->actor()?->id,'to_email'=>$to,'subject'=>$subject,'body'=>$body,'delivery_status'=>'sent','sent_at'=>now()]);$this->activity($app,'email_sent',['to'=>$to,'subject'=>$subject]);return true;}catch(\Throwable $e){$app->messages()->create(['user_id'=>$this->actor()?->id,'to_email'=>$to,'subject'=>$subject,'body'=>$body,'delivery_status'=>'failed','failure_reason'=>mb_substr($e->getMessage(),0,1000)]);$this->activity($app,'email_failed',['to'=>$to]);return false;}}
    private function sendContactMail(ContactInquiry $contact,User $sender,string $subject,string $body): bool {try{if(config('mail.default')==='log')throw new \RuntimeException('Mail is configured for local logging only. Configure SMTP to deliver email.');Mail::raw($body,fn($m)=>$m->to($contact->email)->subject($subject));$contact->replies()->create(['user_id'=>$sender->id,'to_email'=>$contact->email,'subject'=>$subject,'body'=>$body,'delivery_status'=>'sent','sent_at'=>now()]);$contact->update(['status'=>'replied','replied_at'=>now()]);return true;}catch(\Throwable $e){$contact->replies()->create(['user_id'=>$sender->id,'to_email'=>$contact->email,'subject'=>$subject,'body'=>$body,'delivery_status'=>'failed','failure_reason'=>mb_substr($e->getMessage(),0,1000)]);return false;}}

    public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required|string']);$u=User::where('email',$d['email'])->first();if(!$u||!$u->is_admin||!$u->is_active||!Hash::check($d['password'],$u->password))return response()->json(['error'=>'Invalid admin credentials.'],401);$plain=Str::random(64);AdminApiToken::create(['user_id'=>$u->id,'token_hash'=>hash('sha256',$plain),'expires_at'=>now()->addHours(8)]);return response()->json(['token'=>$plain,'id'=>$u->id,'email'=>$u->email,'name'=>$u->name,'role'=>$u->role]);}
    public function logout(Request $r){$r->attributes->get('admin_token')?->delete();return response()->json(['ok'=>true]);}
    public function me(Request $r){return response()->json(['id'=>$r->user()->id,'email'=>$r->user()->email,'name'=>$r->user()->name,'role'=>$r->user()->role]);}
    public function dashboard(){ $counts=CareerApplication::select('status',DB::raw('COUNT(*) as total'))->groupBy('status')->pluck('total','status');$month=now()->startOfMonth()->subMonths(5);$trend=CareerApplication::selectRaw("DATE_FORMAT(submitted_at,'%Y-%m') as month, COUNT(*) as total")->where('submitted_at','>=',$month)->groupBy('month')->orderBy('month')->get()->keyBy('month');$series=[];for($i=0;$i<6;$i++){ $date=$month->copy()->addMonths($i);$key=$date->format('Y-m');$series[]=['label'=>$date->format('M'),'total'=>(int)($trend[$key]->total??0)];}return response()->json(['totalApplications'=>CareerApplication::count(),'openJobs'=>CareerJob::where('is_open',true)->count(),'newContacts'=>ContactInquiry::whereIn('status',['new','in_progress'])->count(),'statusCounts'=>$counts,'monthlyApplications'=>$series,'recentApplications'=>CareerApplication::with('job')->latest('submitted_at')->limit(6)->get()->map(fn($a)=>$this->summary($a))]);}
    public function index(Request $r){$q=CareerApplication::with('job')->when($r->query('status')&&$r->query('status')!=='all',fn($q)=>$q->where('status',$r->query('status')))->when($r->query('job'),fn($q,$v)=>$q->where('career_job_id',$v))->when($r->query('search'),function($q,$v){$q->where(fn($w)=>$w->where('first_name','like','%'.$v.'%')->orWhere('last_name','like','%'.$v.'%')->orWhere('email','like','%'.$v.'%')->orWhere('reference','like','%'.$v.'%')->orWhereHas('job',fn($j)=>$j->where('title','like','%'.$v.'%')));})->latest('submitted_at');return $q->paginate(min(max((int)$r->query('per_page',20),1),100));}
    private function summary($a){return ['id'=>(string)$a->id,'reference'=>$a->reference,'job_title'=>$a->job?->title,'job_reference'=>$a->job?->reference,'first_name'=>$a->first_name,'last_name'=>$a->last_name,'email'=>$a->email,'area_of_interest'=>$a->area_of_interest,'location'=>$a->location,'status'=>$a->status,'submitted_at'=>$a->submitted_at,'created_at'=>$a->created_at];}
    public function show($id){$a=CareerApplication::with(['job','messages','activity'])->findOrFail($id);return response()->json(['application'=>$a,'messages'=>$a->messages->sortByDesc('created_at')->values(),'activity'=>$a->activity->sortByDesc('created_at')->values()]);}
    public function update(Request $r,$id){$a=CareerApplication::findOrFail($id);$d=$r->validate(['status'=>['sometimes',Rule::in(['received','reviewing','interview','rejected','hired','withdrawn'])],'internalNotes'=>'sometimes|nullable|string|max:10000','first_name'=>'sometimes|required|string|max:100','last_name'=>'sometimes|required|string|max:100','email'=>'sometimes|required|email|max:190','phone'=>'sometimes|nullable|string|max:50','location'=>'sometimes|required|string|max:190']);$from=$a->status;$a->fill(collect($d)->only(['first_name','last_name','email','phone','location','internalNotes'])->except('internalNotes')->all());if(array_key_exists('internalNotes',$d))$a->internal_notes=$d['internalNotes'];if(isset($d['status']))$a->status=$d['status'];$a->save();if($from!==$a->status)$this->activity($a,'status_changed',['from'=>$from,'to'=>$a->status]);return response()->json(['application'=>$a]);}
    public function deleteApplication($id){$a=CareerApplication::findOrFail($id);Storage::disk('local')->delete(array_filter([$a->resume_path,$a->supporting_path]));$a->delete();return response()->json(['ok'=>true]);}
    public function reply(Request $r,$id){$d=$r->validate(['subject'=>'required|string|max:180','message'=>'required|string|max:10000']);$a=CareerApplication::findOrFail($id);$ok=$this->sendMail($a,$a->email,$d['subject'],$d['message']);return response()->json(['sent'=>$ok],$ok?200:502);}
    public function download($id,$kind){$a=CareerApplication::findOrFail($id);abort_unless(in_array($kind,['resume','supporting'],true),404);$path=$kind==='resume'?$a->resume_path:$a->supporting_path;$name=$kind==='resume'?$a->resume_name:$a->supporting_name;abort_unless($path&&Storage::disk('local')->exists($path),404);return Storage::disk('local')->download($path,$name);}

    public function adminJobs(Request $r){return CareerJob::withCount(['applications as applications_count'])->when($r->query('search'),fn($q,$v)=>$q->where(fn($w)=>$w->where('title','like','%'.$v.'%')->orWhere('reference','like','%'.$v.'%')->orWhere('department','like','%'.$v.'%')->orWhere('location','like','%'.$v.'%')))->orderByDesc('created_at')->get();}
    private function jobData(Request $r,bool $create=false): array {return $r->validate(['reference'=>[$create?'required':'sometimes','string','max:40',Rule::unique('career_jobs','reference')->ignore($r->route('id'))],'slug'=>['nullable','string','max:180',Rule::unique('career_jobs','slug')->ignore($r->route('id'))],'title'=>[$create?'required':'sometimes','string','max:180'],'location'=>[$create?'required':'sometimes','string','max:180'],'department'=>[$create?'required':'sometimes','string','max:120'],'employment_type'=>[$create?'required':'sometimes','string','max:100'],'summary'=>[$create?'required':'sometimes','string','max:3000'],'responsibilities'=>['nullable','string','max:5000'],'qualifications'=>['nullable','string','max:5000'],'hero_image'=>['nullable','string','max:500'],'is_open'=>['sometimes','boolean']]);}
    public function createJob(Request $r){$d=$this->jobData($r,true);$d['slug']=$d['slug']??$this->slug($d['title']);return response()->json(['job'=>CareerJob::create($d)],201);}
    public function updateJob(Request $r,$id){$job=CareerJob::findOrFail($id);$d=$this->jobData($r);if(isset($d['title'])&&$d['title']!==$job->title&&!isset($d['slug']))$d['slug']=$this->slug($d['title']);$job->update($d);return response()->json(['job'=>$job]);}
    public function deleteJob($id){$job=CareerJob::findOrFail($id);if($job->applications()->exists()){$job->update(['is_open'=>false]);return response()->json(['ok'=>true,'archived'=>true]);}$job->delete();return response()->json(['ok'=>true,'deleted'=>true]);}

    public function contacts(Request $r){return ContactInquiry::withCount('replies')->when($r->query('status')&&$r->query('status')!=='all',fn($q)=>$q->where('status',$r->query('status')))->when($r->query('search'),function($q,$v){$q->where(fn($w)=>$w->where('name','like','%'.$v.'%')->orWhere('email','like','%'.$v.'%')->orWhere('topic','like','%'.$v.'%')->orWhere('reference','like','%'.$v.'%'));})->latest()->paginate(min(max((int)$r->query('per_page',20),1),100));}
    public function showContact($id){$c=ContactInquiry::with(['replies.user:id,name,email','assignee:id,name'])->findOrFail($id);return response()->json(['contact'=>$c]);}
    public function updateContact(Request $r,$id){$c=ContactInquiry::findOrFail($id);$d=$r->validate(['status'=>['sometimes',Rule::in(['new','in_progress','replied','closed'])],'assigned_to'=>'sometimes|nullable|integer|exists:users,id']);$c->update($d);return response()->json(['contact'=>$c]);}
    public function replyContact(Request $r,$id){$d=$r->validate(['subject'=>'required|string|max:180','message'=>'required|string|max:10000']);$c=ContactInquiry::findOrFail($id);$ok=$this->sendContactMail($c,$this->actor(),$d['subject'],$d['message']);return response()->json(['sent'=>$ok],$ok?200:502);}
    public function deleteContact($id){ContactInquiry::findOrFail($id)->delete();return response()->json(['ok'=>true]);}

    public function createDonationInterest(Request $r){$d=$r->validate(['name'=>'required|string|max:160','email'=>'required|email:rfc|max:190','country'=>'nullable|string|max:120','amount'=>'required|numeric|min:1|max:10000000','currency'=>['required',Rule::in(['USD','EUR','CHF','GBP'])],'message'=>'nullable|string|max:2000','consent'=>'required|accepted','website'=>'nullable|string|max:0']);$entry=DonationInterest::create(['reference'=>'SUP-'.strtoupper(Str::random(8)),'name'=>$d['name'],'email'=>$d['email'],'country'=>$d['country']??null,'amount'=>$d['amount'],'currency'=>$d['currency'],'message'=>$d['message']??null,'consent_at'=>now(),'status'=>'new']);return response()->json(['interest'=>['reference'=>$entry->reference],'notice'=>'Your expression of interest is recorded. No donation or payment has been received.'],201);}
    public function donationInterests(Request $r){$this->superadmin();return DonationInterest::withCount('replies')->when($r->query('status')&&$r->query('status')!=='all',fn($q)=>$q->where('status',$r->query('status')))->when($r->query('search'),function($q,$v){$q->where(fn($w)=>$w->where('name','like','%'.$v.'%')->orWhere('email','like','%'.$v.'%')->orWhere('reference','like','%'.$v.'%'));})->latest()->paginate(min(max((int)$r->query('per_page',20),1),100));}
    public function showDonationInterest($id){$this->superadmin();return response()->json(['interest'=>DonationInterest::with(['replies.user:id,name,email'])->findOrFail($id)]);}
    public function updateDonationInterest(Request $r,$id){$this->superadmin();$entry=DonationInterest::findOrFail($id);$d=$r->validate(['status'=>['sometimes',Rule::in(['new','reviewing','contacted','closed'])],'internal_notes'=>'sometimes|nullable|string|max:5000']);$entry->update($d);return response()->json(['interest'=>$entry->fresh()]);}
    public function deleteDonationInterest($id){$this->superadmin();DonationInterest::findOrFail($id)->delete();return response()->json(['ok'=>true]);}
    public function replyDonationInterest(Request $r,$id){$this->superadmin();$d=$r->validate(['subject'=>'required|string|max:180','message'=>'required|string|max:5000']);$entry=DonationInterest::findOrFail($id);$reply=$entry->replies()->create(['user_id'=>$this->actor()->id,'to_email'=>$entry->email,'subject'=>$d['subject'],'body'=>$d['message'],'delivery_status'=>'failed']);try{if(config('mail.default')==='log')throw new \RuntimeException('Mail is configured for local logging only. Configure SMTP to deliver email.');Mail::raw($d['message'],fn($m)=>$m->to($entry->email)->subject($d['subject']));$reply->update(['delivery_status'=>'sent','sent_at'=>now()]);$entry->update(['status'=>'contacted']);return response()->json(['sent'=>true,'reply'=>$reply->fresh()]);}catch(\Throwable $e){$reply->update(['failure_reason'=>mb_substr($e->getMessage(),0,1000)]);return response()->json(['sent'=>false,'error'=>'Email was not delivered. Check the mail configuration.'],502);}}

    public function admins(){$this->superadmin();return User::where('is_admin',true)->orderBy('name')->get(['id','name','email','role','is_active','created_at']);}
    public function createAdmin(Request $r){$this->superadmin();$d=$r->validate(['name'=>'required|string|max:140','email'=>'required|email|max:190|unique:users,email','password'=>'required|string|min:8|max:200','role'=>['required',Rule::in(['admin','superadmin'])]]);$u=User::create($d+['is_admin'=>true,'is_active'=>true]);return response()->json(['admin'=>$u->only(['id','name','email','role','is_active'])],201);}
    public function updateAdmin(Request $r,$id){$this->superadmin();$u=User::where('is_admin',true)->findOrFail($id);$d=$r->validate(['name'=>'sometimes|required|string|max:140','email'=>['sometimes','required','email','max:190',Rule::unique('users','email')->ignore($u->id)],'password'=>'sometimes|nullable|string|min:8|max:200','role'=>['sometimes',Rule::in(['admin','superadmin'])],'is_active'=>'sometimes|boolean']);if($u->id===$this->actor()->id&&(($d['is_active']??true)===false||($d['role']??$u->role)!=='superadmin'))return response()->json(['error'=>'You cannot disable or demote your own account.'],422);if(empty($d['password']))unset($d['password']);$u->update($d);return response()->json(['admin'=>$u->only(['id','name','email','role','is_active'])]);}
    public function deleteAdmin($id){$this->superadmin();$u=User::where('is_admin',true)->findOrFail($id);abort_if($u->id===$this->actor()->id,422,'You cannot delete your own account.');AdminApiToken::where('user_id',$u->id)->delete();$u->delete();return response()->json(['ok'=>true]);}
}
